import{_ as i,o as t,c as e,a5 as o}from"./chunks/framework.Bt0SrEfo.js";const h=JSON.parse('{"title":"中高级前端 8 周重点复习计划（Vue2/3 + React + Next.js + 工程化）","description":"","frontmatter":{},"headers":[],"relativePath":"others/planA/复习计划.md","filePath":"others/planA/复习计划.md","lastUpdated":1788613730000}'),r={name:"others/planA/复习计划.md"};function s(a,l,n,u,g,p){return t(),e("div",null,[...l[0]||(l[0]=[o('<h1 id="中高级前端-8-周重点复习计划-vue2-3-react-next-js-工程化" tabindex="-1">中高级前端 8 周重点复习计划（Vue2/3 + React + Next.js + 工程化） <a class="header-anchor" href="#中高级前端-8-周重点复习计划-vue2-3-react-next-js-工程化" aria-label="Permalink to &quot;中高级前端 8 周重点复习计划（Vue2/3 + React + Next.js + 工程化）&quot;">​</a></h1><blockquote><p>每天 2~3 小时，周一～周五新知识，周末复盘项目 目标：扎实掌握框架原理 + SSR/工程化能力 + 高频面试题</p></blockquote><hr><h2 id="第-1-周-javascript-typescript-进阶-必备原理" tabindex="-1">第 1 周：JavaScript / TypeScript 进阶（必备原理） <a class="header-anchor" href="#第-1-周-javascript-typescript-进阶-必备原理" aria-label="Permalink to &quot;第 1 周：JavaScript / TypeScript 进阶（必备原理）&quot;">​</a></h2><p><strong>目标</strong>：理解 JS 核心机制与 TS 类型系统，为框架原理打基础</p><ul><li><strong>理论学习</strong>： <ul><li>作用域、闭包、执行上下文、原型链</li><li>Event Loop、微任务/宏任务</li><li>Promise / async/await / 手写 Promise</li><li>TypeScript 基础：泛型、类型推断、工具类型</li></ul></li><li><strong>小练习</strong>： <ul><li>手写闭包计数器 / debounce / deepClone</li><li>TypeScript 改写小函数</li></ul></li><li><strong>面试题</strong>： <ul><li>JS 闭包、原型链、事件循环原理</li><li>TS 泛型使用场景</li></ul></li><li><strong>周末复盘</strong>： <ul><li>输出《JS/TS 核心原理总结》笔记</li><li>实现一个小型函数工具库（闭包 + TS 泛型）</li></ul></li></ul><hr><h2 id="第-2-周-vue2-核心机制-必备" tabindex="-1">第 2 周：Vue2 核心机制（必备） <a class="header-anchor" href="#第-2-周-vue2-核心机制-必备" aria-label="Permalink to &quot;第 2 周：Vue2 核心机制（必备）&quot;">​</a></h2><p><strong>目标</strong>：掌握 Vue2 响应式、Diff算法、组件通信和状态管理</p><ul><li><strong>理论学习</strong>： <ul><li>响应式原理（Object.defineProperty）</li><li>虚拟 DOM / Diff 算法</li><li>生命周期 / nextTick / 组件通信</li><li>Vuex / Vue Router</li></ul></li><li><strong>小练习</strong>： <ul><li>手写简易响应式系统</li><li>父子组件通信 demo</li><li>TodoList（Vue2 + Vuex + Router）</li></ul></li><li><strong>面试题</strong>： <ul><li>Vue2 响应式实现原理</li><li>Diff 算法优化点</li><li>Vuex 数据流</li></ul></li><li><strong>周末复盘</strong>： <ul><li>完整 TodoList 项目</li><li>输出《Vue2 原理与通信机制笔记》</li></ul></li></ul><hr><h2 id="第-3-周-vue3-composition-api-必备" tabindex="-1">第 3 周：Vue3 &amp; Composition API（必备） <a class="header-anchor" href="#第-3-周-vue3-composition-api-必备" aria-label="Permalink to &quot;第 3 周：Vue3 &amp; Composition API（必备）&quot;">​</a></h2><p><strong>目标</strong>：掌握 Vue3 新特性和 Pinia 状态管理</p><ul><li><strong>理论学习</strong>： <ul><li>Proxy 响应式机制</li><li>setup / ref / reactive / computed</li><li>Composition API / watchEffect</li><li>Pinia 状态管理</li><li>生命周期钩子</li></ul></li><li><strong>小练习</strong>： <ul><li>TodoList 用 Composition API + Pinia 改写</li><li>自定义 Hook（useFetch / useToggle）</li></ul></li><li><strong>面试题</strong>： <ul><li>Vue3 响应式 vs Vue2</li><li>Composition API 优势</li><li>Pinia 优势与使用场景</li></ul></li><li><strong>周末复盘</strong>： <ul><li>输出《Vue3 原理 + Pinia 使用笔记》</li><li>项目性能优化实验</li></ul></li></ul><hr><h2 id="第-4-周-react-核心与-hooks-必备" tabindex="-1">第 4 周：React 核心与 Hooks（必备） <a class="header-anchor" href="#第-4-周-react-核心与-hooks-必备" aria-label="Permalink to &quot;第 4 周：React 核心与 Hooks（必备）&quot;">​</a></h2><p><strong>目标</strong>：掌握 React 渲染机制、Hooks、状态管理</p><ul><li><strong>理论学习</strong>： <ul><li>虚拟 DOM / Diff 算法 / Fiber 架构</li><li>Hooks（useState/useEffect/useMemo/useCallback/useRef）</li><li>Context / Redux / Zustand</li><li>React Router 6 与懒加载</li></ul></li><li><strong>小练习</strong>： <ul><li>手写简易 useState/useEffect</li><li>Redux TodoList</li><li>Router 动态路由与懒加载</li></ul></li><li><strong>面试题</strong>： <ul><li>Fiber 架构原理</li><li>useEffect 依赖机制</li><li>组件复用优化</li></ul></li><li><strong>周末复盘</strong>： <ul><li>React 项目总结</li><li>输出《React 原理与优化笔记》</li></ul></li></ul><hr><h2 id="第-5-周-next-js-ssr-ssg-isr-必备" tabindex="-1">第 5 周：Next.js SSR/SSG/ISR（必备） <a class="header-anchor" href="#第-5-周-next-js-ssr-ssg-isr-必备" aria-label="Permalink to &quot;第 5 周：Next.js SSR/SSG/ISR（必备）&quot;">​</a></h2><p><strong>目标</strong>：理解 SSR 原理、数据获取、Server Components</p><ul><li><strong>理论学习</strong>： <ul><li>SSR / CSR / SSG / ISR 原理与区别</li><li>App Router / Pages Router</li><li>数据获取方法：getServerSideProps / getStaticProps</li><li>Server Components / Client Components</li><li>SEO 优化</li></ul></li><li><strong>小练习</strong>： <ul><li>构建博客项目，实现 SSR / SEO</li><li>动态路由与懒加载页面</li></ul></li><li><strong>面试题</strong>： <ul><li>SSR 优势与应用场景</li><li>Hydration 机制</li><li>Next.js 数据预取流程</li></ul></li><li><strong>周末复盘</strong>： <ul><li>项目 SSR 实战</li><li>输出《Next.js SSR &amp; SEO 总结》</li></ul></li></ul><hr><h2 id="第-6-周-前端工程化基础-必备" tabindex="-1">第 6 周：前端工程化基础（必备） <a class="header-anchor" href="#第-6-周-前端工程化基础-必备" aria-label="Permalink to &quot;第 6 周：前端工程化基础（必备）&quot;">​</a></h2><p><strong>目标</strong>：掌握打包、构建与模块化原理</p><ul><li><strong>理论学习</strong>： <ul><li>Webpack / Vite / Rollup 原理</li><li>Tree Shaking / 代码分割 / 按需加载</li><li>Loader / Plugin 机制</li><li>模块化开发（ESM / CommonJS / UMD）</li></ul></li><li><strong>小练习</strong>： <ul><li>配置简易 Webpack / Vite 工程</li><li>实现 Tree Shaking 测试</li></ul></li><li><strong>面试题</strong>： <ul><li>打包优化方案</li><li>Tree Shaking 原理</li><li>模块化设计思路</li></ul></li><li><strong>周末复盘</strong>： <ul><li>小型前端工程项目</li><li>输出《工程化原理总结笔记》</li></ul></li></ul><hr><h2 id="第-7-周-前端工程化进阶-必备" tabindex="-1">第 7 周：前端工程化进阶（必备） <a class="header-anchor" href="#第-7-周-前端工程化进阶-必备" aria-label="Permalink to &quot;第 7 周：前端工程化进阶（必备）&quot;">​</a></h2><p><strong>目标</strong>：性能优化、缓存策略、CI/CD 实践</p><ul><li><strong>理论学习</strong>： <ul><li>前端性能优化策略（懒加载、虚拟列表、首屏优化）</li><li>缓存策略 / CDN / 压缩</li><li>CI/CD 自动化部署</li></ul></li><li><strong>小练习</strong>： <ul><li>优化已有 Vue3 或 React 项目</li><li>配置简单 CI/CD 流程</li></ul></li><li><strong>面试题</strong>： <ul><li>性能优化方案</li><li>缓存策略原理</li><li>自动化部署流程</li></ul></li><li><strong>周末复盘</strong>： <ul><li>输出《性能优化 + 工程化实践笔记》</li></ul></li></ul><hr><h2 id="第-8-周-综合项目-面试复盘" tabindex="-1">第 8 周：综合项目 + 面试复盘 <a class="header-anchor" href="#第-8-周-综合项目-面试复盘" aria-label="Permalink to &quot;第 8 周：综合项目 + 面试复盘&quot;">​</a></h2><p><strong>目标</strong>：整合前7周知识，输出面试可讲项目与框架原理</p><ul><li><strong>综合实践</strong>： <ul><li>Vue3 + React + Next.js 项目整合</li><li>框架原理总结</li><li>工程化优化整合</li></ul></li><li><strong>面试输出</strong>： <ul><li>项目经验讲述模板（技术选型 + 原理 + 性能优化）</li><li>高频面试题口述练习</li></ul></li><li><strong>周末复盘</strong>： <ul><li>完成终极复盘笔记</li><li>输出《中高级前端复习手册》</li></ul></li></ul><p>![](Pasted image 20251102001739.png)</p>',35)])])}const S=i(r,[["render",s]]);export{h as __pageData,S as default};
